package br.com.juh.kwaifacil;
import android.content.*; import android.database.Cursor; import android.net.Uri; import android.provider.DocumentsContract; import org.json.*; import java.io.*; import java.util.*;
final class QueueStore {
 static class Item {String name,uri,caption,state="Pendente";int confirmationRetries=0; Item(String n,String u,String c){name=n;uri=u;caption=c;}}
 static ArrayList<Item> items=new ArrayList<>();static Context ctx;static int current=-1;static volatile boolean running=false, importing=false;static ComponentName destination;static String notice="Escolha uma pasta com 001.mp4 e 001.txt, 002.mp4 e 002.txt…";
 static void init(Context c){if(ctx!=null)return;ctx=c.getApplicationContext();try{JSONArray a=new JSONArray(ctx.getSharedPreferences("queue",0).getString("items","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);Item x=new Item(o.getString("name"),o.getString("uri"),o.getString("caption"));x.state=o.getString("state");x.confirmationRetries=o.optInt("confirmationRetries",0);if(x.state.equals("Em andamento"))x.state="Precisa de atenção";items.add(x);}save();}catch(Exception e){notice="Não foi possível restaurar a fila.";}}
 static void save(){JSONArray a=new JSONArray();for(Item x:items){try{JSONObject o=new JSONObject();o.put("name",x.name);o.put("uri",x.uri);o.put("caption",x.caption);o.put("state",x.state);o.put("confirmationRetries",x.confirmationRetries);a.put(o);}catch(Exception ignored){}}ctx.getSharedPreferences("queue",0).edit().putString("items",a.toString()).commit();}
 static void scan(Uri tree)throws Exception{String id=DocumentsContract.getTreeDocumentId(tree);Uri child=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);TreeMap<String,Uri> all=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);try(Cursor c=ctx.getContentResolver().query(child,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException("Pasta indisponível");while(c.moveToNext()){String name=c.getString(1);if(all.containsKey(name))throw new IOException("Nomes duplicados na pasta (ignorando maiúsculas/minúsculas)");all.put(name,DocumentsContract.buildDocumentUriUsingTree(tree,c.getString(0)));}}
 ArrayList<Item> imported=new ArrayList<>();for(Map.Entry<String,Uri> e:all.entrySet()){String n=e.getKey();if(!n.toLowerCase(Locale.ROOT).matches(".*\\.(mp4|mov|m4v|webm)$"))continue;String base=n.substring(0,n.lastIndexOf('.'));Uri txt=all.get(base+".txt");String text="";if(txt!=null){try(InputStream in=ctx.getContentResolver().openInputStream(txt);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Não foi possível abrir a legenda: "+n);byte[] buf=new byte[4096];int k;while((k=in.read(buf))!=-1){out.write(buf,0,k);if(out.size()>32768)throw new IOException("Legenda maior que 32 KB: "+n);}text=new String(out.toByteArray(),"UTF-8").replace("\uFEFF","").trim();}}
 Item x=new Item(n,e.getValue().toString(),text);if(text.isEmpty())x.state="Sem legenda";for(Item old:items)if(old.uri.equals(x.uri)&&old.caption.equals(text)){x.confirmationRetries=old.confirmationRetries;if(!old.state.equals("Em andamento"))x.state=old.state;}imported.add(x);}
 items=imported;current=-1;save();notice=items.size()+" vídeo(s) carregado(s). Toque em cada item para revisar.";}
 static int pending(){for(int i=0;i<items.size();i++)if(items.get(i).state.equals("Pendente"))return i;return -1;}
 static boolean uncertain(){for(Item x:items)if(x.state.equals("Precisa de atenção")||x.state.equals("Em andamento"))return true;return false;}
 static void pause(String reason){running=false;Run.active=false;if(current>=0&&current<items.size()&&items.get(current).state.equals("Em andamento"))items.get(current).state="Precisa de atenção";notice=reason;Run.status=reason;save();}
 static void retryUnconfirmed(){if(!running||current<0||current>=items.size()){pause("A publicação ficou sem confirmação. Confira o perfil antes de continuar.");return;}Item x=items.get(current);if(x.confirmationRetries>=1){pause("A segunda tentativa também ficou sem confirmação. Confira o perfil do Kwai antes de tentar novamente.");return;}x.confirmationRetries++;x.state="Pendente";Run.active=false;Run.sent=false;Run.sentAt=0;notice="Não localizei a legenda após três checagens. Tentarei este vídeo novamente uma vez.";Run.status=notice;save();if(KwaiService.instance!=null)KwaiService.instance.h.postDelayed(()->{if(running)launch(ctx);},5000);else pause("Assistente desconectado. Confira o perfil antes de tentar novamente.");}
 static void launch(Context c){if(!running)return;if(destination==null){pause("Escolha novamente o Kwai antes de continuar a fila.");return;}int i=pending();if(i<0){running=false;notice="Fila concluída. Confira os vídeos no perfil do Kwai.";Run.status=notice;return;}current=i;if(KwaiService.instance!=null){KwaiService.instance.captionMismatchSince=0;KwaiService.instance.hashtagRetry=false;KwaiService.instance.hashtagRetries=0;KwaiService.instance.warningUntil=0;KwaiService.instance.last=0;KwaiService.instance.lastScreen="";KwaiService.instance.verificationAttempts=0;KwaiService.instance.lastProfileCheckAttempt=0;KwaiService.instance.finalVerificationUntil=0;}Item x=items.get(i);x.state="Em andamento";save();CaptionSpec spec;try{spec=new CaptionSpec(x.caption);}catch(Exception e){pause(x.name+": "+e.getMessage());return;}
 Run.coverSeconds=spec.seconds;Run.coverDuration=0;Run.coverDone=spec.seconds<0;Run.coverStage=0;
 if(spec.caption.isEmpty()){pause("Legenda vazia: "+x.name);return;}
 if(spec.seconds>=0){android.media.MediaMetadataRetriever reader=new android.media.MediaMetadataRetriever();try{reader.setDataSource(ctx,Uri.parse(x.uri));Run.coverDuration=Double.parseDouble(reader.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION))/1000.0;if(Run.coverDuration<=0||spec.seconds>=Run.coverDuration)throw new IllegalArgumentException();}catch(Exception e){pause("Tempo da capa fora do vídeo ou duração indisponível: "+x.name);return;}finally{try{reader.release();}catch(Exception ignored){}}}
 Run.caption=spec.caption;Run.target=destination.getPackageName();Run.started=System.currentTimeMillis();Run.sentAt=0;Run.advances=0;Run.filled=false;Run.sent=false;Run.active=true;Run.status="Publicando "+x.name;Uri u=Uri.parse(x.uri);Intent s=new Intent(Intent.ACTION_SEND).setType("video/*").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_ACTIVITY_NEW_TASK).setComponent(destination);s.setClipData(ClipData.newRawUri("Vídeo",u));try{c.startActivity(s);}catch(Exception e){pause("Não foi possível abrir o próximo vídeo. Confira a fila.");}}
 static void success(){if(!running||!Run.active||!Run.sent||current<0||current>=items.size())return;items.get(current).state="Publicado";save();Run.active=false;notice="Publicação confirmada pelo Kwai.";if(KwaiService.instance!=null)KwaiService.instance.h.postDelayed(()->{if(running)launch(ctx);},8000);else pause("Assistente desconectado após confirmação. Confira a fila antes de continuar.");}
}
